create table if not exists private.dd_catalog_provider_master (id uuid primary key default gen_random_uuid(), provider_key text not null unique, display_name text not null, role_class text not null check (role_class in ('COMMERCIAL_OWNER','FULFILLMENT_PROVIDER','INTERNAL_SPECIALIST','EXTERNAL_SPECIALIST')), commercial_owner boolean not null default false, fulfillment_eligible boolean not null default false, economic_benchmark numeric, economic_unit text, qualification_status text not null default 'PENDING_RECONCILIATION' check (qualification_status in ('VERIFIED','PENDING_RECONCILIATION','NOT_REQUIRED','NOT_ELIGIBLE')), agreement_status text not null default 'PENDING_RECONCILIATION', notes text, source_authority text not null default 'Phase 0.5 Provider Master Reconciliation', lifecycle_state text not null default 'PENDING_RECONCILIATION' check (lifecycle_state in ('CANONICAL_ACTIVE','ABSORBED_REDIRECTED','DEPRECATED_HISTORICAL','PENDING_RECONCILIATION')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists private.dd_catalog_provider_capability_master (id uuid primary key default gen_random_uuid(), provider_key text not null references private.dd_catalog_provider_master(provider_key) on delete cascade, capability_key text not null, division_id integer not null check (division_id between 1 and 13), eligibility_status text not null default 'PENDING_RECONCILIATION' check (eligibility_status in ('ELIGIBLE','CONDITIONAL','PENDING_RECONCILIATION','INELIGIBLE')), scope_boundary text, required_qualification text, equipment_dependency text, source_authority text not null default 'Phase 0.5 Provider Capability Reconciliation', notes text, unique(provider_key, capability_key));
create table if not exists private.dd_catalog_inventory_master (id uuid primary key default gen_random_uuid(), inventory_key text not null unique, owner_key text not null, asset_class text not null check (asset_class in ('EQUIPMENT','TOOL','CONSUMABLE','CHEMICAL','SUPPLY','DIGITAL_ASSET','VEHICLE','OTHER')), item_name text not null, brand_model text, quantity numeric not null default 1, condition_status text not null check (condition_status in ('OPERATIONAL','LIMITED','BROKEN','DEPLETED','UNKNOWN','NOT_OWNED')), custody_status text not null default 'OWNED' check (custody_status in ('OWNED','PROVIDER_OWNED','CLIENT_OWNED','BORROWED','LEASED','NOT_OWNED')), availability_status text not null default 'AVAILABLE' check (availability_status in ('AVAILABLE','LIMITED','UNAVAILABLE','DEPLETED','UNKNOWN')), supports_capabilities text[] not null default '{}', exclusion_note text, source_authority text not null default 'Verified Inventory Reconciliation', lifecycle_state text not null default 'PENDING_RECONCILIATION' check (lifecycle_state in ('CANONICAL_ACTIVE','ABSORBED_REDIRECTED','DEPRECATED_HISTORICAL','PENDING_RECONCILIATION')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists private.dd_catalog_capability_dependency_master (id uuid primary key default gen_random_uuid(), capability_key text not null, dependency_type text not null check (dependency_type in ('CAPABILITY','EQUIPMENT','SUPPLY','PROVIDER','QUALIFICATION','LOGISTICS','COMPLIANCE')), dependency_key text not null, requirement_status text not null default 'PENDING_RECONCILIATION' check (requirement_status in ('REQUIRED','CONDITIONAL','OPTIONAL','PENDING_RECONCILIATION','NOT_AVAILABLE')), notes text, source_authority text not null default 'Phase 0.5 Dependency Reconciliation', unique(capability_key, dependency_type, dependency_key));
create index if not exists idx_provider_capability_division on private.dd_catalog_provider_capability_master(division_id);
create index if not exists idx_inventory_owner on private.dd_catalog_inventory_master(owner_key);
create index if not exists idx_dependency_capability on private.dd_catalog_capability_dependency_master(capability_key);
insert into private.dd_catalog_provider_master (provider_key, display_name, role_class, commercial_owner, fulfillment_eligible, economic_benchmark, economic_unit, qualification_status, agreement_status, notes, lifecycle_state) values ('DANI','DANI DECLARES / DANI','COMMERCIAL_OWNER',true,true,null,null,'VERIFIED','INTERNAL_AUTHORITY','Commercial ownership, customer relationship, pricing authority and primary operations/QA.','CANONICAL_ACTIVE'),('CAYLA','Cayla','FULFILLMENT_PROVIDER',false,false,20,'USD_PER_HOUR','PENDING_RECONCILIATION','PENDING_RECONCILIATION','Indoor plant-care specialization; $20/hr is an internal benchmark only and never customer pricing.','PENDING_RECONCILIATION'),('CHRIS','Chris','INTERNAL_SPECIALIST',false,false,null,null,'PENDING_RECONCILIATION','PENDING_RECONCILIATION','Computer/technical support plus DTF/heat-press/media production capabilities; ownership of equipment must remain asset-specific.','PENDING_RECONCILIATION'),('CASS','Cass','FULFILLMENT_PROVIDER',false,false,null,null,'PENDING_RECONCILIATION','PENDING_RECONCILIATION','Business/financial/bookkeeping/project administration support subject to documented scope and qualification.','PENDING_RECONCILIATION'),('NAWFside','NAWFside','FULFILLMENT_PROVIDER',false,false,null,null,'PENDING_RECONCILIATION','EXECUTED','Property/facilities/trade fulfillment lane; existing DB capability rows remain unauthorized until reconciled.','PENDING_RECONCILIATION'),('EXTERNAL_SPECIALIST','Qualified External Specialist','EXTERNAL_SPECIALIST',false,false,null,null,'PENDING_RECONCILIATION','PENDING_RECONCILIATION','Used where licensing, certification, veterinary, grooming, electrical, plumbing, HVAC, legal, or other specialist boundaries require it.','PENDING_RECONCILIATION') on conflict (provider_key) do update set display_name=excluded.display_name, role_class=excluded.role_class, commercial_owner=excluded.commercial_owner, economic_benchmark=excluded.economic_benchmark, economic_unit=excluded.economic_unit, notes=excluded.notes, lifecycle_state=excluded.lifecycle_state, updated_at=now();
insert into private.dd_catalog_inventory_master (inventory_key, owner_key, asset_class, item_name, brand_model, quantity, condition_status, custody_status, availability_status, supports_capabilities, exclusion_note, lifecycle_state) values ('INV-DANI-STEAM-MC1385','DANI','EQUIPMENT','Steam cleaner','McCulloch MC1385',1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Does not imply commercial extraction capability.','CANONICAL_ACTIVE'),('INV-DANI-BISSELL','DANI','EQUIPMENT','Bissell cleaning machine/vacuum',null,1,'LIMITED','OWNED','LIMITED',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Bissell is present, but its hose is broken; do not classify as a fully operational carpet extractor.','CANONICAL_ACTIVE'),('INV-DANI-DEGREASER-ZEP','DANI','CHEMICAL','Degreaser','Zep',1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Consumable quantity must be rechecked before production jobs.','CANONICAL_ACTIVE'),('INV-DANI-ODOBAN','DANI','CHEMICAL','Odor-control cleaner','OdoBan',1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Do not represent as hazardous/biohazard remediation capability.','CANONICAL_ACTIVE'),('INV-DANI-MICROFIBER','DANI','SUPPLY','Microfiber towels',null,1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Quantity not yet counted.','PENDING_RECONCILIATION'),('INV-DANI-TRASH-BAGS-55','DANI','SUPPLY','55-gallon trash bags',null,1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT','CAP-12-LOG'],'Quantity not yet counted.','PENDING_RECONCILIATION'),('INV-DANI-ROACH-GEL','DANI','CHEMICAL','Roach gel',null,1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Pest-control chemical use must remain within applicable legal/product-label boundaries; does not create a licensed pest-control service.','CANONICAL_ACTIVE'),('INV-DANI-ROACH-TRAPS','DANI','SUPPLY','Roach traps',null,1,'OPERATIONAL','OWNED','AVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Does not create a licensed pest-control service.','CANONICAL_ACTIVE'),('INV-DANI-BROOM','DANI','TOOL','Broom',null,1,'BROKEN','OWNED','UNAVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'Broken; not available for fulfillment.','CANONICAL_ACTIVE'),('INV-DANI-DRILL','DANI','TOOL','Drill',null,0,'NOT_OWNED','NOT_OWNED','UNAVAILABLE',array['CAP-01A-MAINT','CAP-02B-MAINT'],'No drill currently held; do not assume availability.','CANONICAL_ACTIVE'),('INV-DANI-AIRFILTER','DANI','EQUIPMENT','Air filter/air purifier',null,1,'BROKEN','OWNED','UNAVAILABLE',array['CAP-01A-CLEAN','CAP-01A-MAINT'],'One unit reported not working; not available for fulfillment.','CANONICAL_ACTIVE'),('INV-CHRIS-DTF-HEATPRESS','CHRIS','EQUIPMENT','DTF/heat-press production equipment',null,1,'UNKNOWN','PROVIDER_OWNED','UNKNOWN',array['CAP-11C-APPAREL'],'Exact model, count and condition require provider inventory verification.','PENDING_RECONCILIATION'),('INV-CHRIS-COMPUTER-MEDIA','CHRIS','EQUIPMENT','Computer/media production equipment',null,1,'UNKNOWN','PROVIDER_OWNED','UNKNOWN',array['CAP-06C-COMPUTER','CAP-06D-SYSTEMS','CAP-07C-PHOTO','CAP-07D-VIDEO'],'Exact asset inventory and condition require provider verification.','PENDING_RECONCILIATION') on conflict (inventory_key) do update set condition_status=excluded.condition_status, custody_status=excluded.custody_status, availability_status=excluded.availability_status, supports_capabilities=excluded.supports_capabilities, exclusion_note=excluded.exclusion_note, updated_at=now();
insert into private.dd_catalog_capability_dependency_master (capability_key, dependency_type, dependency_key, requirement_status, notes) values ('CAP-01A-CLEAN','EQUIPMENT','INV-DANI-STEAM-MC1385','REQUIRED','Primary verified steam-cleaning equipment.'),('CAP-01A-CLEAN','EQUIPMENT','INV-DANI-BISSELL','CONDITIONAL','Bissell is present but limited by broken hose; never treat it as an operational commercial carpet extractor.'),('CAP-01A-MAINT','EQUIPMENT','INV-DANI-DRILL','NOT_AVAILABLE','No drill currently held.'),('CAP-11C-APPAREL','EQUIPMENT','INV-CHRIS-DTF-HEATPRESS','PENDING_RECONCILIATION','Provider-owned equipment; verify before commercial routing.'),('CAP-06C-COMPUTER','EQUIPMENT','INV-CHRIS-COMPUTER-MEDIA','PENDING_RECONCILIATION','Provider-owned technical equipment; verify before routing.'),('CAP-07D-VIDEO','EQUIPMENT','INV-CHRIS-COMPUTER-MEDIA','PENDING_RECONCILIATION','Provider-owned media equipment; verify before routing.') on conflict (capability_key, dependency_type, dependency_key) do update set requirement_status=excluded.requirement_status, notes=excluded.notes;
revoke all on private.dd_catalog_provider_master from anon, authenticated;
revoke all on private.dd_catalog_provider_capability_master from anon, authenticated;
revoke all on private.dd_catalog_inventory_master from anon, authenticated;
revoke all on private.dd_catalog_capability_dependency_master from anon, authenticated;